class TaskManager:
    """Manages a collection of tasks with support for adding, removing,
    marking complete, and filtering by status."""

    def __init__(self):
        self.tasks = []

    def add(self, t):
        """Add a new task to the manager."""
        self.tasks.append({"text": t, "status": "pending"})

    def remove(self, t):
        """Remove a task by its text content."""
        self.tasks = [task for task in self.tasks if task["text"] != t]

    def mark_complete(self, t):
        """Mark a task as complete by its text content."""
        for task in self.tasks:
            if task["text"] == t:
                task["status"] = "complete"
                break

    def list(self, status=None):
        """List all tasks, optionally filtered by status ('pending' or 'complete').

        Returns a comma-separated string of task texts.
        """
        if status is None:
            filtered_tasks = self.tasks
        else:
            filtered_tasks = [task for task in self.tasks if task["status"] == status]

        if not filtered_tasks:
            return ""

        task_texts = [task["text"] for task in filtered_tasks]
        return ", ".join(task_texts)
